package dev.veltraph.client.mixinbootstrap;
import org.junit.jupiter.api.Test;
import org.objectweb.asm.Opcodes;
import org.objectweb.asm.tree.*;
import static org.junit.jupiter.api.Assertions.*;
/** Actual plugin capture over concrete ASM original source layouts; no native phase or game execution is fabricated. */
class RootNativeTickIngressSourceOrderTest {
    private static final String MC="net/minecraft/client/Minecraft",RENDERER="net/minecraft/client/renderer/GameRenderer";
    private static final String CAMERA="dev.veltraph.client.mixin.RootNativeCameraIngressMixin",GAMEPLAY="dev.veltraph.client.mixin.RootNativeGameplayTickMixin",SDL="dev.veltraph.client.mixin.RootNativeSdlClientMixin";
    private static MethodNode method(String name,String desc){return new MethodNode(Opcodes.ACC_PUBLIC,name,desc,null,null);}
    private static void call(MethodNode source,int opcode,String owner,String name,String desc){source.instructions.add(new MethodInsnNode(opcode,owner,name,desc,false));}
    private static MethodNode runTick(){var m=method("runTick","(Z)V");call(m,Opcodes.INVOKEVIRTUAL,MC,"tick","()V");call(m,Opcodes.INVOKEVIRTUAL,MC,"renderFrame","(Z)V");call(m,Opcodes.INVOKEVIRTUAL,"net/minecraft/client/MouseHandler","handleAccumulatedMovement","()V");m.instructions.add(new InsnNode(Opcodes.RETURN));return m;}
    private static ClassNode original(){var target=new ClassNode();target.name=MC;var run=method("run","()V");call(run,Opcodes.INVOKEVIRTUAL,MC,"runTick","(Z)V");call(run,Opcodes.INVOKESTATIC,"com/mojang/blaze3d/systems/RenderSystem","pollEvents","(Lcom/mojang/blaze3d/platform/SDLEventHandler;)V");run.instructions.add(new InsnNode(Opcodes.RETURN));var tick=method("tick","()V");tick.instructions.add(new InsnNode(Opcodes.RETURN));var render=method("renderFrame","(Z)V");call(render,Opcodes.INVOKEVIRTUAL,RENDERER,"update","(Lnet/minecraft/client/DeltaTracker;)V");render.instructions.add(new InsnNode(Opcodes.RETURN));target.methods.add(run);target.methods.add(runTick());target.methods.add(tick);target.methods.add(render);return target;}
    private static MethodNode get(ClassNode target,String name){return target.methods.stream().filter(m->m.name.equals(name)).findFirst().orElseThrow();}
    private static Object field(RootNativeTickIngressPlugin plugin,String name){try{var f=RootNativeTickIngressPlugin.class.getDeclaredField(name);f.setAccessible(true);return f.get(plugin);}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
    private static void apply(RootNativeTickIngressPlugin plugin,ClassNode target,String mixin){plugin.preApply(MC,target,mixin,null);}
    private static RootNativeTickIngressPlugin plugin(ClassNode target){var p=new RootNativeTickIngressPlugin();apply(p,target,"dev.veltraph.client.mixin.OwnedRotationTickMixin");return p;}
    @Test void cameraFirstRetainsActualRunTickAndLaterGameplayAndSDLRequireSameIdentity(){var t=original();var p=plugin(t);apply(p,t,CAMERA);assertSame(get(t,"runTick").instructions,field(p,"originalRunTick"));assertSame(get(t,"renderFrame").instructions,field(p,"originalRenderFrame"));apply(p,t,GAMEPLAY);apply(p,t,SDL);assertSame(get(t,"runTick").instructions,field(p,"originalRunTick"));}
    @Test void gameplayFirstThenCameraAndSDLConserveSameOriginalBody(){var t=original();var p=plugin(t);apply(p,t,GAMEPLAY);var retained=field(p,"originalRunTick");apply(p,t,CAMERA);apply(p,t,SDL);assertSame(retained,field(p,"originalRunTick"));}
    @Test void SDLFirstThenCameraAndGameplayConserveSameOriginalBody(){var t=original();var p=plugin(t);apply(p,t,SDL);var retained=field(p,"originalRunTick");apply(p,t,CAMERA);apply(p,t,GAMEPLAY);assertSame(retained,field(p,"originalRunTick"));}
    @Test void cameraFirstCannotAuthorizeStructurallyEqualDifferentGameplayBody(){var t=original();var p=plugin(t);apply(p,t,CAMERA);var retained=field(p,"originalRunTick");get(t,"runTick").instructions=runTick().instructions;assertThrows(IllegalStateException.class,()->apply(p,t,GAMEPLAY));assertSame(retained,field(p,"originalRunTick"));}
    @Test void gameplayFirstRejectsDifferentLaterCameraBody(){var t=original();var p=plugin(t);apply(p,t,GAMEPLAY);var retained=field(p,"originalRunTick");get(t,"runTick").instructions=runTick().instructions;assertThrows(IllegalStateException.class,()->apply(p,t,CAMERA));assertSame(retained,field(p,"originalRunTick"));assertNull(field(p,"originalRenderFrame"));}
    @Test void missingOriginalRenderCallNeverSeedsRunTick(){var t=original();var p=plugin(t);var m=get(t,"runTick");for(var n=m.instructions.getFirst();n!=null;){var next=n.getNext();if(n instanceof MethodInsnNode c&&c.name.equals("renderFrame"))m.instructions.remove(n);n=next;}assertThrows(IllegalStateException.class,()->apply(p,t,CAMERA));assertNull(field(p,"originalRunTick"));assertNull(field(p,"originalRenderFrame"));}
    @Test void duplicateOriginalRenderCallNeverSeedsRunTick(){var t=original();var p=plugin(t);call(get(t,"runTick"),Opcodes.INVOKEVIRTUAL,MC,"renderFrame","(Z)V");assertThrows(IllegalStateException.class,()->apply(p,t,CAMERA));assertNull(field(p,"originalRunTick"));}
    @Test void duplicateRunTickMethodNeverSeedsSource(){var t=original();var p=plugin(t);t.methods.add(runTick());assertThrows(IllegalStateException.class,()->apply(p,t,CAMERA));assertNull(field(p,"originalRunTick"));}
    @Test void missingRendererUpdateNeverSeedsAnyCameraSource(){var t=original();var p=plugin(t);get(t,"renderFrame").instructions.clear();assertThrows(IllegalStateException.class,()->apply(p,t,CAMERA));assertNull(field(p,"originalRunTick"));assertNull(field(p,"originalRenderFrame"));}
    @Test void duplicateRendererUpdateNeverSeedsAnyCameraSource(){var t=original();var p=plugin(t);call(get(t,"renderFrame"),Opcodes.INVOKEVIRTUAL,RENDERER,"update","(Lnet/minecraft/client/DeltaTracker;)V");assertThrows(IllegalStateException.class,()->apply(p,t,CAMERA));assertNull(field(p,"originalRunTick"));assertNull(field(p,"originalRenderFrame"));}
    @Test void duplicateCameraCaptureStillRefuses(){var t=original();var p=plugin(t);apply(p,t,CAMERA);assertThrows(IllegalStateException.class,()->apply(p,t,CAMERA));}
    @Test void laterSDLStillRejectsReplacementRunTickIdentity(){var t=original();var p=plugin(t);apply(p,t,CAMERA);var retained=field(p,"originalRunTick");get(t,"runTick").instructions=runTick().instructions;assertThrows(IllegalStateException.class,()->apply(p,t,SDL));assertSame(retained,field(p,"originalRunTick"));}
}
